Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='gateworkspace', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='The pre-merge gate covers the whole workspace with all targets and the fixture feature', body='Run clippy over the whole workspace, all targets, with the fixture feature and warnings denied. Also run the live and guards tests, which a plain workspace test run skips. Run a per-crate gate only for a pure leaf change. Never export a variable that the gate itself keys on.', rationale='A change to a public sum or struct breaks crates the change never opened, and a gate that lists crates tells nothing about the others.', supersedes=()))